param([ValidateSet('build','selftest','capture')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-mantissa-row-certificate-20260913';$seed='D:\projects\AIMA-public-final-pv-bound-20260913-r2';$sha='b7296d431bcf9e843a987bf4c832bb8282ee90d5';$bundle='D:\projects\mantissa-row-certificate-b7296d4.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '8033de8914a5f96947e38afab459efe58d954d0cf4551f693e075ab6b05c5d0c'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\row-certificate';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\mantissa_row_certificate_probe.cpp';$exe=Join-Path $build 'row-certificate.exe'
$sourceInputs=@();$sourceFiles=@($source)+@(Get-ChildItem (Join-Path $repo 'native\providers\moe_accumulator') -Filter '*.h' -File|ForEach-Object {$_.FullName})
foreach($file in $sourceFiles){$sourceInputs+=@{file=$file;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; CPU row-certificate diagnostic';model_loaded=$false;inference_acceptance=$false;cpu_partials_only=$true;performance_acceptance=$false;purpose='Characterize coarse exact BF16 mantissa-row eligibility before choosing a native QK replacement'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-ffp-contract=off','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=120
}else{
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$spec.arguments=@('--selftest');$timeout=90
 if($Action -eq 'capture'){
  $capRoot='D:\projects\AIMA-public-fa-out-20260911\build\fla-model-q7169-fa-out-r1'
  $q=Join-Path $capRoot 'layer3-full-full_attention_q_norm_rope-bf16.bin';$k=Join-Path $capRoot 'layer3-full-full_attention_k_norm_rope-bf16.bin'
  $sources=@(@{file=$q;sha256='c04de09df4879842e299db9822c76e0b6e13a70c345cb9803d74722e25f24b7d'},@{file=$k;sha256='99bd880e732fd2786c12a68113fe5f834b5cc0fe87b09b0aaf5734c90bf3f2e8'})
  foreach($file in $sources){if((Get-FileHash $file.file -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Original QK capture changed'}}
  $spec.input_files=$sources;$spec.arguments=@('--q7169',$q,$k)
  $spec.model='D:\models\Qwen3.6-35B-A3B; captured real q7169 layer3 QK, CPU diagnostic only'
  $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83'
  $spec.input_run_sha256='4a4334d65056371866a10626bec395f9778a2cb6a182ead0560c35ea5cb20146'
  $spec.input_whole_source='28c4f9df501e8e95ac357acc45d30daf48633bf8'
 }
}
$specPath=Join-Path $build ($Action+'-spec-r1.json');$out=Join-Path $repo ('build\row-certificate-'+$Action+'-r1')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 12}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $expected=if($Action -eq 'capture'){2}else{1};$groups=if($Action -eq 'capture'){2097152}else{1048576}
 if($reports.Count -ne $expected -or $reports[0].groups -ne $groups -or $reports[0].canonical_value_mismatches -ne 0 -or -not $reports[0].cpu_partials_only){throw 'Incomplete certificate diagnostic'}
}

