run-native-mantissa-row-wmma-r1.ps1.text:
param([ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-mantissa-row-wmma-20260913'
$seed='D:\projects\AIMA-public-ck-transpose-20260911'
$sha='d33d5b89ea052fc4db87840120548fed80f2ca27'
$bundle='D:\projects\mantissa-row-wmma-d33d5b8.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '483f37746d75da3977c2c04de5c8b2438f7361b527f6eb23ac56f1efab5ff851'){throw 'Bundle fingerprint mismatch'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD
 if($LASTEXITCODE -ne 0){throw 'Bundle fetch failed'}
 & git -C $seed worktree add --detach $repo $sha
 if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\mantissa-probe'
$null=New-Item -ItemType Directory -Path $build -Force
$exe=Join-Path $build 'mantissa-probe.exe'
$artifacts=@();foreach($file in @('tests\native\sm121_mantissa_wmma_selftest.cpp','native\providers\ck_fmha\blackwell_attention.h','native\providers\moe_accumulator\sm121_mantissa_parts.h','native\providers\moe_accumulator\sm121_native_product.h','native\providers\moe_accumulator\sm121_group16_modulo.h','native\providers\moe_accumulator\q1_moe_hawkeye_bf16_accumulator.h','native\providers\moe_accumulator\sm121_wave16.h','native\providers\gdn\sm121_exp2_table.h','native\providers\gdn\sm121_attention_rcp.h')){$path=Join-Path $repo $file;$artifacts+=@{file=$path;sha256=(Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant()}}
foreach($directory in @('native/providers/moe_accumulator','native/providers/gdn')){foreach($file in @(Get-ChildItem (Join-Path $repo $directory) -Filter '*.h' -File)){$artifacts+=@{file=$file.FullName;sha256=(Get-FileHash $file.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}}
$spec=[ordered]@{executable=$exe;arguments=@();working_directory=$repo;repo_commit=$sha;source_inputs=$artifacts;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();model='none; generated BF16 arithmetic controls, coarse row reconstruction with actual GPU partials';row_certificate_probe=$true;performance_acceptance=$false;model_loaded=$false;inference_acceptance=$false;purpose=$Action}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){$spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe';$spec.arguments=@('-std=c++17','-O3','-DQRT_MANTISSA_ROW_CERTIFICATE_PROBE=1','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',(Join-Path $repo 'tests\native\sm121_mantissa_wmma_selftest.cpp'),'-o',$exe);$timeout=120}else{
 $provenance=[IO.File]::ReadAllText((Join-Path $build 'build-provenance.json'))|ConvertFrom-Json
 if($provenance.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $provenance.executable.sha256){throw 'Binary provenance mismatch'}
 $spec.arguments=@('--selftest');$timeout=30
}
$out=Join-Path $repo ('build\mantissa-probe-'+$Action+'-r2');$specPath=Join-Path $build ($Action+'-spec-r2.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Output exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout | Out-Null
$record=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$record|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($file in @('product.stdout.jsonl','product.stderr.log')){[IO.File]::ReadAllText((Join-Path $out $file))}
if($record.reason -ne 'completed' -or -not $record.host_checks_pass -or ($record.exit_code -ne 0 -and -not ($Action -eq 'test' -and $record.exit_code -eq 2))){throw 'Native action or host check failed'}
if($Action -eq 'build'){
 $manifest=@{repo_commit=$sha;source_inputs=$artifacts;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($manifest|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}
